import math


def fib(n: int):
    if n <= 0:
        raise ValueError("Input must be a positive integer")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        # Use matrix exponentiation to calculate n-th Fibonacci number in O(log n) time
        matrix_pow = {}
        matrix_pow[1] = [[1, 1], [1, 0]]
        matrix = matrix_pow[n-1]

        # Compute matrix to the power of (n-1) using power method
        def multiply_matrices(A, B):
            return [[sum(a * b for a, b in zip(A_row, B_col)) for B_col in zip(*B)] for A_row in A]

        def power(A, n):
            if n == 1:
                return A
            elif n % 2:
                return multiply_matrices(A, power(A, n-1))
            else:
                half_power = power(A, n // 2)
                return multiply_matrices(half_power, half_power)

        # Calculate the n-th Fibonacci number using exponentiation by squaring
        return power(matrix, n)[0][0]

# Demonstrate the function's usage with example calls
if __name__ == "__main__":
    print(fib(10))  # 55
    print(fib(1))   # 0
    print(fib(8))   # 21
