def is_equal_to_sum_even(n):
    # First, check if the input number n is even or not, as it should be even.
    if n % 2 != 0:
        return False

    # Now, we find at least 4 even factors of n.
    # For this, we'll use the fact that an even number has at least two factors: 1 and itself.
    # We'll use quadratic residues and Legendre symbol to find potential even factors quickly.

    # This function checks if a number is a quadratic residue (meaning it has a square root modulo some odd number)
    # and if it's a prime number. We'll use this in our logic to find even factors.
    def is_quadratic_residue(p, x):
        return pow(x, (p - 1) // 2, p) == 1

    # Check if n is a prime number, as it simplifies the process of finding even factors.
    if n < 2:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):  # Only test odd numbers (even numbers are excluded)
        if n % i == 0:
            # Found a divisor, check if it's even.
            if i % 2 == 0:
                # Divisor is even, now we reduce n by this divisor and find new even factors.
                n //= i
                # Continue this process to find at least 4 even factors.
                if n % 2 != 0:
                    return False
            # Otherwise, it's an odd divisor, but if it's prime, the rest of the number may not have even factors.
            elif is_prime(i) and is_quadratic_residue(i, n):
                # If it's a prime, and it's a quadratic residue of n, we reduce n and continue searching.
                continue
            else:
                # Found an odd divisor, break as we cannot form 4 even factors now.
                break
        if n == 1:
            return True  # n is prime and does not divide 1, thus all parts are even by default.

    return n >= 4  # If this point is reached, n is even and has at least 4 factors, one of which is 2.


