import operator


def do_algebra(operator, operand):
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,  # Assuming floor division as // is not needed as per the given operations
        '**': operator.pow
    }

    if len(operator) != len(operand) - 1:
        raise ValueError("The length of the operator list must be one less than the length of the operand list.")

    if not all(isinstance(i, int) and i >= 0 for i in operand):
        raise ValueError("All elements in operand list must be non-negative integers.")

    result = operand[0]

    for i, op in enumerate(operator):
        if op not in ops:
            raise ValueError(f"Invalid operator '{op}' found.")
        result = ops[op](result, operand[i + 1])

    return result

```

